head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.gBzTyp = '';
scwin.vScrenID = 'ULDSTF30007.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_getParam = function() {
    var vTemp = frame.FrameID;
    var Temp2 = vTemp.split("|")[1];
    var Temp3 = vTemp.split("|")[2];
    if (Temp3 != undefined) {
        scwin.gBzTyp = Temp3.split("=")[1];
    }
    var vISUR_CD = Temp2.split("=")[1];
    $c.stf.setObjectValue(txb_ISUR_CD, vISUR_CD);
};
scwin.fn_resizeToWin = function() {
    frame.Width = 480;
    frame.Height = 530;
};
scwin.fn_HideDebugCtrls = function() {
    // 키값으로 사용하지만 화면상에 표시될 필요가 없는 것들
    $c.stf.showObj(panel_debug, false);
};
scwin.fn_Init = function() {
    edt_FromDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 365)); // 1년전 날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    scwin.fn_SetPar = $c.frame.path("../").scwin.fn_SetPar;
    //fn_list_sync();

};
scwin.fn_list_sync = function() {
    var url = '';
    //alert('[gBzTyp]'+gBzTyp);
    if (scwin.gBzTyp == 'A') {
        url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=LIST_DSCL_FOR_REG" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.dsclmgt.select.report.term" + "&{P}param01=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&{P}param02=" + $c.stf.getObjectValue(edt_FromDate) + "&{P}param03=" + $c.stf.getObjectValue(edt_ToDate) + // 종료일자
            "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    } else {
        url = "/DisclosureSchedule.do?method=listDsclForReg";
        url += "&SEARCH_TYP=Y";
        url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
        url += "&STRT_DD=" + $c.stf.getObjectValue(edt_FromDate);
        url += "&END_DD=" + $c.stf.getObjectValue(edt_ToDate);
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    }
    dts_Discls.DataID = encodeURI(url);
    dts_Discls.Reset();
};
scwin.setAcpt_No = async function(GridID, row, ColID) {
    var arrPar = new Array();
    var rtn = undefined;
    var objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..
    if (scwin.fn_SetPar == "fn_setDiscls") {
        //온라인통보에서 공시시각을 셋팅한다.
        //alert(fn_SetPar);
        arrPar[0] = objDataID.getCellData(row, "ACPT_NO");
        arrPar[1] = objDataID.getCellData(row, "DISCLS_TITLE");
        arrPar[2] = objDataID.getCellData(row, "DISCLS_PUBL_DDTM");
        rtn = scwin.fn_SetPar(arrPar);
    } else if (scwin.fn_SetPar != undefined) {
        arrPar[0] = objDataID.getCellData(row, "ACPT_NO");
        arrPar[1] = objDataID.getCellData(row, "DISCLS_TITLE");
        arrPar[2] = objDataID.getCellData(row, "DISCLS_PUBL_DDTM");
        rtn = scwin.fn_SetPar(arrPar);
    }
    if ((rtn == undefined) || (rtn)) {
        await $c.frame.CloseFrame();
    }
};
scwin.dts_Discls_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
};
scwin.grd_Discls_OnDblClick = function(row, colid) {
    scwin.setAcpt_No(grd_Discls, row, colid);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_FromDate, edt_ToDate);
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_HideDebugCtrls();
    scwin.fn_resizeToWin();
    scwin.fn_getParam();
    scwin.fn_Init();
    scwin.fn_list_sync();
};
